#include <iostream>
#include <cstring>
#include <algorithm>
#include <cctype>
using namespace std;

const int MAX = 15;
int pathDist[MAX][MAX][MAX][MAX];
int edgeCap[400][400];
char bioGrid[20][20];
char reactMap[20][20];
int dirX[4] = {1,0,-1,0};
int dirY[4] = {0,1,0,-1};
int iterStep = 3;
int visitStatus[400];

int gridSize, maxTime;

int DFS(int cur, int dst, int bottleneck) {
    if (cur == dst) return bottleneck;
    if (visitStatus[cur] == iterStep) return 0;
    visitStatus[cur] = iterStep;
    for (int next = 0; next <= dst; ++next) {
        int pushed = 0;
        if (edgeCap[cur][next] > 0 && (pushed = DFS(next, dst, min(bottleneck, edgeCap[cur][next])))) {
            edgeCap[cur][next] -= pushed;
            edgeCap[next][cur] += pushed;
            return pushed;
        }
    }
    return 0;
}

inline int getIdx(int r, int c) {
    return (r-1)*gridSize + (c-1);
}

int spreadGrid[13][13];
int tempSpread[13][13];

void spread(int mark) {
    copy(&spreadGrid[0][0], &spreadGrid[0][0]+169, &tempSpread[0][0]);
    for (int r = 1; r <= gridSize; ++r) {
        for (int c = 1; c <= gridSize; ++c) {
            if (tempSpread[r][c] == mark) {
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dirX[d];
                    int nc = c + dirY[d];
                    if (nr > 0 && nc > 0 && nr <= gridSize && nc <= gridSize && spreadGrid[nr][nc] < mark && bioGrid[nr][nc] != 'Y') {
                        spreadGrid[nr][nc] = mark;
                    }
                }
            }
        }
    }
}

bool pathExists(int sx, int sy, int tx, int ty, int infx, int infy) {
    memset(spreadGrid, 0, sizeof(spreadGrid));
    spreadGrid[sx][sy] = 1;
    spreadGrid[infx][infy] = 2;
    for (int step = 0; step < 100; ++step) {
        spread(1);
        if (spreadGrid[tx][ty] == 1) return true;
        spread(2);
        if (spreadGrid[tx][ty] == 2) return false;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int infx = -1, infy = -1;
    memset(pathDist, 0x01, sizeof(pathDist));
    cin >> gridSize >> maxTime;

    for (int i = 1; i <= gridSize; ++i) {
        cin >> (bioGrid[i] + 1);
        for (int j = 1; j <= gridSize; ++j) {
            pathDist[i][j][i][j] = 0;
            if (bioGrid[i][j] == 'Z') {
                infx = i; infy = j;
            }
        }
    }

    for (int i = 1; i <= gridSize; ++i) {
        cin >> (reactMap[i] + 1);
    }

    for (int i = 1; i <= gridSize; ++i) {
        for (int j = 1; j <= gridSize; ++j) {
            for (int d = 0; d < 4; ++d) {
                int ni = i + dirX[d];
                int nj = j + dirY[d];
                if (ni >= 1 && nj >= 1 && ni <= gridSize && nj <= gridSize) {
                    if (bioGrid[i][j] != 'Y' && bioGrid[ni][nj] != 'Y') {
                        pathDist[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }

    for (int k = 1; k <= gridSize; ++k) {
        for (int l = 1; l <= gridSize; ++l) {
            for (int i = 1; i <= gridSize; ++i) {
                for (int j = 1; j <= gridSize; ++j) {
                    for (int u = 1; u <= gridSize; ++u) {
                        for (int v = 1; v <= gridSize; ++v) {
                            pathDist[i][j][u][v] = min(pathDist[i][j][u][v], pathDist[i][j][k][l] + pathDist[k][l][u][v]);
                        }
                    }
                }
            }
        }
    }

    int sourceNode = gridSize * gridSize * 2 + 1;
    int sinkNode = gridSize * gridSize * 2 + 2;

    for (int i = 1; i <= gridSize; ++i) {
        for (int j = 1; j <= gridSize; ++j) {
            if (isdigit(bioGrid[i][j])) {
                edgeCap[sourceNode][getIdx(i, j)] = bioGrid[i][j] - '0';
            }
            if (isdigit(reactMap[i][j])) {
                edgeCap[gridSize*gridSize + getIdx(i, j)][sinkNode] = reactMap[i][j] - '0';
            }

            if (isdigit(bioGrid[i][j])) {
                for (int u = 1; u <= gridSize; ++u) {
                    for (int v = 1; v <= gridSize; ++v) {
                        if (bioGrid[i][j] > '0' && reactMap[u][v] > '0') {
                            if (isdigit(reactMap[u][v]) && pathDist[i][j][u][v] <= maxTime && pathExists(i,j,u,v,infx,infy)) {
                                edgeCap[getIdx(i, j)][gridSize*gridSize + getIdx(u, v)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }

    int flowTotal = 0;
    int augmentFlow;
    while ((augmentFlow = DFS(sourceNode, sinkNode, 1000))) {
        flowTotal += augmentFlow;
        ++iterStep;
    }

    cout << flowTotal << '\n';
    return 0;
}
